extra_processor_methods:
static std::string getLoopsDirectory() {
        auto base = juce::File::getSpecialLocation(juce::File::userApplicationDataDirectory);
#if JUCE_MAC
        base = base.getChildFile("Application Support");
#endif
        const auto dir = base.getChildFile("AbacDsp").getChildFile("Tapelooper").getChildFile("loops");
        dir.createDirectory();
        return dir.getFullPathName().toStdString();
    }

extra_menus.build_method:
juce::PopupMenu buildGrooveMenu()
{
    const auto names = processorRef.listGrooveNames();
    juce::String currentStyle = processorRef.getCurrentGrooveName();
    const int lastSlash = currentStyle.lastIndexOfChar('/');
    const int vPos = currentStyle.lastIndexOf("_v");
    if (vPos > lastSlash) { currentStyle = currentStyle.substring(0, vPos); }
    return buildGroupedMenu(names, {ID_BASE}, currentStyle);
}

extra_menus.select_method:
void handleGrooveMenuSelection(int menuItemID)
{
    const auto names = processorRef.listGrooveNames();
    if (menuItemID >= {ID_BASE} && menuItemID < {ID_BASE} + static_cast<int>(names.size()))
    {
        const auto& style = names[static_cast<size_t>(menuItemID - {ID_BASE})];
        processorRef.requestLoadGroove(style, 0);
        m_statusBar.showMessage("Loading groove '" + style + "'...");
    }
}
